using System.Collections.Generic;
using mumu;
using TMPro;
using Unity.Collections;
using UnityEngine;
using UnityEngine.UI;

// Generated by Claude Code
public class Block : MonoBehaviour
{
    [SerializeField]
    private Image image;
    [SerializeField]
    private TextMeshProUGUI text;

    private eBlockType blockType;
    private List<eBlockSubType> blockSubTypes = new();
    public int SortIndex { get; private set; }

    public eBlockType BlockType
    {
        get { return blockType; }
        set { blockType = value; }
    }

    // Generated by Claude Code
    public void AddSubType(eBlockSubType _subType)
    {
        if (!blockSubTypes.Contains(_subType))
        {
            blockSubTypes.Add(_subType);
            applyBlockTypeVisual();
        }
    }

    // Generated by Claude Code
    public void RemoveSubType(eBlockSubType _subType)
    {
        blockSubTypes.Remove(_subType);
    }

    // Generated by Claude Code
    public bool HasSubType(eBlockSubType _subType)
    {
        return blockSubTypes.Contains(_subType);
    }

    private void setColor(Color color)
    {
        image.color = color;
    }

    // Generated by Claude Code
    public void SetBlockType(eBlockType _type)
    {
        blockType = _type;
        applyBlockTypeVisual();
    }

    public void SetOrder(int x, int y, int maxX, int maxY)
    {
        // 🔥 Row-based ordering (top → bottom)
        // y = 0 (top row) → smallest index
        // increases downward
        SortIndex = (maxX*maxY) - (y * maxX + x);
    }
    public void SetDubugText()
    {
        text.text = SortIndex.ToString()+" "+blockType; // debug
    }

    private void applyBlockTypeVisual()
    {
        // Check for subtypes first
        if (HasSubType(eBlockSubType.Waypoint))
        {
            gameObject.SetActive(true);
            setColor(Color.magenta);
            return;
        }

        // Apply base block type colors
        switch (blockType)
        {
            case eBlockType.Empty:
                gameObject.SetActive(false);
                break;
            case eBlockType.Walkable:
                gameObject.SetActive(true);
                break;
            case eBlockType.Obstruct:
                gameObject.SetActive(true);
                setColor(Color.red);
                break;
            case eBlockType.Start:
                gameObject.SetActive(true);
                setColor(Color.blue);
                break;
            case eBlockType.Goal:
                gameObject.SetActive(true);
                setColor(Color.yellow);
                break;
        }
    }
}
